    [97183] = "Vuelve con la gualdrapa de arcanita bendecida junto a Danitha Morr en el Castillo Bandarion, en los Claros de Tirisfal.",
    [97184] = "Lleva un diamante azerothiano y un diamante negro prístino a Danitha Morr en el Castillo Bandarion, en los Claros de Tirisfal.",
    [97185] = "Usa el Arúspice en el corazón del sótano del Gran Osario de Scholomance. Al hacerlo, aparecerán los espíritus que debes juzgar. Al derrotar a esos espíritus, invocarás al caballero de la Muerte Darkreaver. Derrótalo y recupera el alma perdida del destrero caído.$B$BEntrega el espíritu de reprensión y la gualdrapa encantada bendecida al destrero caído de Darkreaver.",
    [97186] = "Consigue 20 galletas de maná enriquecidas para Nathanos Clamañublo en las Tierras de la Peste del Este. El Alba Argenta es el único proveedor conocido de estas galletas. También tendrás que darle a Clamañublo 50 monedas de oro por su tiempo.",
    [97197] = "Recupera un fragmento de las Tierras de Fuego de las Profundidades de Roca Negra y llévaselo a Alaana Caminatormentas en Mulgore.",
    [97198] = "Recupera un tótem de ritual Faucenegra en el Bastión Faucenegra.",
    [97243] = "Llévale la antorcha de la llama latente a Olariaan Ardeveloz en el santuario de las llamas que está en las Tierras Bajas de los Soplabayas.",
    [97244] = "Asesina al sacerdote del cielo Faladiel en las Tierras Bajas de los Soplabayas y consigue su corazón.",
    [97245] = "Encuentra el hogar de Kuramaa en las Tierras Altas de Shen'dar y derrota a este espíritu en combate. Llévale la máscara de Kuramaa a Olariaan Ardeveloz en las Tierras Bajas de los Soplabayas una vez que te alces con la victoria.",
    [97250] = "Mata a los soldados de la Alianza que han invadido Los Baldíos en la frontera con el Marjal Revolcafango y luego vuelve con el bruto Logmar en el Campamento Taurajo.",
    [97257] = "Espera a que Olariaan empiece el ritual en el blandón de ofrendas y sigue sus instrucciones.",
    [97288] = "Entrega la cabeza abominable al maestro boticario Faranell en Entrañas.",
    [97289] = "Lleva la cabeza del barón junto al cuerpo de Othmar en Entrañas.",
    [97290] = "Informa de tus hallazgos al maestro boticario Faranell de Entrañas.",
    [97291] = "Visita a Tawny Grisette en el Barrio del Comercio para conseguir un capacete tóxico, a los instructores de herboristería para reunir hierba ampolla y a la vendedora de venenos del Barrio de los Pícaros para obtener esencia de agonía. Lleva todo al maestro boticario Faranell de Entrañas.",
    [97292] = "Inyecta el suero siseante en el sistema que hay sobre el cuerpo de Othmar para el maestro boticario Faranell.",
    [97327] = "Entra en el Bastión Faucenegra y recupera 5 faltriqueras de los Faucenegra para Ekkal en las Ruinas de Eldarath de Azshara.",
    [97411] = "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales Forjaluz a Mokvar, en Orgrimmar.",
    [97412] = "Lleva un cinturón forjaluz y unos guanteletes forjaluz a Mokvar en Orgrimmar.",
    [97413] = "Vuelve con Mokvar en Orgrimmar llevando unas botas forjaluz, unos quijotes forjaluz y unas bufas forjaluz.",
    [97447] = "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de ataduras de elementos a Deliana, en Forjaz.",
    [97448] = "Lleva un cordón de los elementos y unos guanteletes de los elementos a Deliana en Forjaz.",
    [97449] = "Vuelve con Deliana en Forjaz llevando unas botas de los elementos, una falda de los elementos y unos espaldares de los elementos.",
    [97450] = "Entrégale a Deliana tu cofia de los elementos y tu jubón de los elementos.",
    [98094] = "La suma ejecutora Darthalia quiere que le entregues las nuevas órdenes al mortacechador Masoj, que se encuentra al sur de Molino Tarren, justo a las afueras de Dun Garok.",
    [98095] = "El mortacechador Masoj necesita que coloques tres viales de apotecarios en los lugares claves de las Laderas de Trabalomas. Después, regresa con él.",
    [98096] = "Busca a la comandante Cantocertero en Punta Talrendis, en Azshara, y pregúntale por el paradero de Keldara Filosol.",
    [98298] = "Llévale 6 tapitas de huargen a Dalar Tejealba en El Sepulcro.",
    [98299] = "Mata a 5 refugiados enfermos y a 5 refugiados demacrados para Dalar Tejealba en El Sepulcro.",
    [98325] = "Habla con el señor de la guerra Dientegore para ponerte al servicio de la Fuerza Expedicionaria de Kargath.",
    [98340] = "Habla con Dendrita Rafagaestelar en el poblado Amparo de la Noche, en Claro de la Luna.",
    [98341] = "Busca al avatar de Saeyleenan al sur de Claro de la Luna y descubre lo que tiene que mostrarte sobre la naturaleza del felino natoviento.",
    [98342] = "Recupera la reliquia del colmillo, la reliquia de la garra y la reliquia de la sombra silenciosa en el Túmulo de Tempestira. Después, entrégaselas al gran espíritu felino.",
    [98362] = "Vuelve a Cima del Trueno para hablar con Turak Tótem Rúnico en Alto de los Ancestros.",
    [98393] = "Habla con Dendrita Rafagaestelar en el poblado Amparo de la Noche, en Claro de la Luna.",
    [98394] = "Busca al gran espíritu felino al sur de Claro de la Luna y descubre lo que tiene que mostrarte sobre la naturaleza del felino.",
    [98396] = "Recupera la reliquia del colmillo, la reliquia de la garra y la reliquia de la sombra silenciosa en el Túmulo de Tempestira. Después, entrégaselas al gran espíritu felino.",
    [98397] = "Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion.",
    [98404] = "Recupera la reliquia del colmillo, la reliquia de la garra y la reliquia de la sombra silenciosa en el Túmulo de Tempestira. Después, entrégaselas al avatar de Saeyleenan.",
    [98405] = "Busca al gran espíritu felino al sur de Claro de la Luna y descubre lo que tiene que mostrarte sobre la naturaleza del felino.",
    [98447] = "Encuentra la causa que provoca la presencia de los fantasmas de la familia Valor en el Cerro del Cuervo para Sirra Von'Indi, que está en Villa Oscura.",
    [98512] = "Mata 10 asesinos Al'Aketh en las Tierras Altas de Shen'dar.",
    [98517] = "Habla con Sessaria Caminante del Cielo o Aarnor Choquevendaval en la Isla de Zephras para proseguir con tu instrucción de chamán.$B$BPara volver a Zephras, puedes usar el cortacielos de Mulgore, que atraca en la Meseta de Miracielos, al noroeste de Cima del Trueno.",
    [98731] = "Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso.  Después ve a hablar con Dendrite Rafagaestelar a Amparo de la Noche.",
    [98738] = "Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso.  Después ve a hablar con Dendrite Rafagaestelar a Amparo de la Noche.",
    [98739] = "Habla con Dendrita.",
    [98830] = "Entrega la guja rota de Tortheldrin al ancestro Shen'dralar, que está en La Masacre.",
    [99187] = "Ve al Bastión Faucenegra, en Kalimdor, y recupera el relicario de Tyr.",
    [99257] = "Mata a un protector de pilón decrépito para obtener su corazón de cristal agotado y llévaselo al Historiador Biraxas, en el templo de Shen'dralas.",
    [99258] = "Arroja el corazón de cristal agotado a una falla de maná inestable. Vuelve con el Historiador Biraxas, en el templo de Shen'dralas, con pruebas de tu éxito o tu fracaso.",
    [99260] = "Habla con Elaadrin Vendaval del Atardecer en Valanaar.",
    [99435] = "Sigue a Reginald Windsor por Ventormenta. ¡Protégele del peligro!\\n\\nHabla con el escudero Rowe si necesitas volver a contactar con Reginald Windsor.",
    [99670] = "Vuelve con Jereman en la Cuna de la Tranquilidad.",
}
